  ".drawing .dr-dot { fill: currentColor; }",
  ".mark { display: block; flex: none; }",
  ".mark svg { display: block; width: 100%; height: 100%; }",
  "",
  ".wrap { max-width: 1240px; margin: 0 auto; padding: 26px 28px 0; }",
  ".greet { display: flex; align-items: baseline; gap: 4px 18px; flex-wrap: wrap; }",
  ".greet h1 { font: 600 32px/1.15 var(--serif); letter-spacing: -0.02em; color: var(--semantic-color-fg-strong); }",
  ".greet .verdict { font: 19px/1.4 var(--serif); color: var(--semantic-color-fg-default); margin: 0; }",
  ".greet .verdict em { font-style: normal; color: var(--semantic-color-accent-default); }",
  ".wrap > p.meta { margin: 8px 0 0; font: 12.5px/1.4 var(--mono); color: var(--semantic-color-fg-muted); }",
