  ".chip.warn::before, .chip.ok::before { content: \"\"; flex: none; width: 6px; height: 6px; border-radius: 50%;",
  "  background: var(--semantic-color-status-warn); }",
  ".chip.ok::before { background: var(--semantic-color-accent-default); }",
  "/* the price ladder on a family's pages (ruled 21 Sep): the three tiers in order, the page in hand lit */",
  ".ladder { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; margin: 16px 0 0; padding: 0; list-style: none;",
  "  font: 500 12px/1.3 var(--sans); color: var(--semantic-color-fg-muted); }",
  ".ladder li { display: inline-flex; align-items: center; gap: 8px; }",
  ".ladder li + li::before { content: \"\\203A\"; color: var(--semantic-color-fg-faint); }",
  ".ladder .step { border: 1px solid var(--semantic-color-border-default); border-radius: var(--semantic-radius-pill); padding: 3px 10px; }",
  ".ladder .step b { font-weight: 600; }",
  ".ladder .is-here { color: var(--semantic-color-fg-strong); border-color: var(--semantic-color-accent-default);",
  "  background: var(--semantic-color-accent-soft); }",
  "",
  "/* the strip of counts: monospaced, and only a numeral that asks for something carries colour */",
  ".numbers { display: grid; grid-template-columns: repeat(auto-fit, minmax(118px, 1fr)); margin-top: 18px; overflow: hidden;",
  "  background: var(--semantic-color-bg-paper); border: 1px solid var(--semantic-color-border-default);",
  "  border-radius: var(--semantic-radius-card); box-shadow: var(--semantic-shadow-card); }",
  ".numbers .c { min-width: 0; padding: 13px 16px 12px;",
  "  box-shadow: -1px 0 0 var(--semantic-color-border-default), 0 -1px 0 var(--semantic-color-border-default); }",
  ".numbers b { display: block; font: 500 27px/1.1 var(--mono); font-variant-numeric: tabular-nums; color: var(--semantic-color-fg-strong); }",
  ".numbers .k-act b { color: var(--semantic-color-status-bad-text); }",
  ".numbers .k-due b { color: var(--semantic-color-status-warn-text); }",
