  ".numbers .status { display: flex; font-size: 11px; line-height: 1.3; color: var(--semantic-color-fg-muted); margin-top: 3px; }",
  "",
  "/* jumps to each section, as the inbox's filter pills: a dot, a word, a count */",
  ".jumps { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }",
  ".jump { display: inline-flex; align-items: center; gap: 7px; padding: 5px 11px; border-radius: var(--semantic-radius-pill);",
  "  border: 1px solid var(--semantic-color-border-strong); background: var(--semantic-color-bg-paper);",
