  "  .ledger-t td { padding: 0; border: 0; } .ledger-t td + td { margin-top: 6px; } td.act { text-align: left; }",
  "  .block > .row { grid-template-columns: minmax(0, 1fr); gap: 2px; padding: 12px 16px; }",
