// The desk's funnel and the card beside it (row E6), as the team view and the snapshot both set
// them: one partial, opening each of the two pages' own CSS, so neither keeps a second copy.
const FUNNEL_CSS = [
  "/* The desk's funnel and the card beside it, as the two pages that draw them set them (the macros are",
  "   `funnel` and `stall_card` in macros.html.j2). Included into a page's own page_css block, so a page that",
  "   draws the funnel says so in one line and neither page keeps a second copy of these rules. */",
  "/* the desk as a whole leads a page: the funnel on the left, and on the right the step the numbers",
  "   themselves name as the worst drop, with the counts that could explain it under it */",
  ".desk-grid { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 26px; align-items: start; }",
  ".fn-card { background: var(--semantic-color-bg-paper); border: 1px solid var(--semantic-color-border-default);",
  "  border-top: 2px solid var(--semantic-color-accent-default);",
  "  border-radius: 0 0 var(--semantic-radius-card) var(--semantic-radius-card);",
  "  box-shadow: var(--semantic-shadow-card); padding: 14px 24px 20px; }",
  "/* a step: its count in a column of its own, its name, and a bar drawn against the first step. The tail",
  "   behind a bar is what fell away on the way into it, and the line above says how many and how many carried */",
  ".fn-step { display: grid; grid-template-columns: 4.6ch minmax(0, 1fr); column-gap: 18px; row-gap: 0; }",
  ".fn-step + .fn-step::before { content: \"\"; grid-column: 1; grid-row: 1; justify-self: center;",
  "  border-left: 1px dashed var(--semantic-color-border-strong); }",
  ".fn-step.is-stall::before { border-left-color: var(--semantic-color-status-warn); }",
  ".fn-fell { grid-column: 2; grid-row: 1; margin: 0; padding: 10px 0 11px; display: flex; align-items: baseline;",
  "  flex-wrap: wrap; gap: 2px 10px; font-size: 12.5px; line-height: 1.35; color: var(--semantic-color-fg-muted); }",
  ".fn-fell b { font: 500 13.5px/1.3 var(--mono); font-variant-numeric: tabular-nums; color: var(--semantic-color-fg-strong); }",
  ".fn-fell .status { font-size: 11.5px; }",
  ".fn-kept { margin-left: auto; font: 11.5px/1.3 var(--mono); font-variant-numeric: tabular-nums;",
  "  color: var(--semantic-color-fg-faint); white-space: nowrap; }",
  ".fn-step.is-stall .fn-fell, .fn-step.is-stall .fn-fell b { color: var(--semantic-color-status-warn-text); }",
  ".fn-v { grid-column: 1; grid-row: 2 / 4; align-self: center; text-align: right; font: 500 26px/1 var(--mono);",
  "  font-variant-numeric: tabular-nums; color: var(--semantic-color-fg-strong); }",
  ".fn-step.is-stall .fn-v { color: var(--semantic-color-status-warn-text); }",
  ".fn-lbl { grid-column: 2; grid-row: 2; margin: 0; font: 600 15px/1.3 var(--serif); color: var(--semantic-color-fg-strong); }",
  ".fn-bar { grid-column: 2; grid-row: 3; position: relative; height: 12px; margin-top: 7px;",
  "  border-radius: 3px; background: var(--semantic-color-bg-sheet); overflow: hidden;",
  "  box-shadow: inset 0 0 0 1px var(--semantic-color-border-default); }",
  ".fn-tail, .fn-fill { position: absolute; left: 0; top: 0; bottom: 0; }",
  "/* the tail is read against the ground either way round, so it is the page's own muted ink, not a border */",
  ".fn-tail { background: var(--semantic-color-fg-muted); opacity: .28; }",
  ".fn-step.is-stall .fn-tail { background: var(--semantic-color-status-warn); opacity: .45; }",
  ".fn-fill { background: var(--semantic-color-accent-default); border-radius: 3px 0 0 3px; }",
  ".fn-step:first-child .fn-fill { border-radius: 3px; }",
  "/* the stall, said in a sentence from the numbers, then the three counts the desk already holds under it */",
  ".stall { position: relative; overflow: hidden; background: var(--semantic-color-bg-paper);",
  "  border: 1px solid var(--semantic-color-border-default); border-radius: var(--semantic-radius-card);",
  "  box-shadow: var(--semantic-shadow-card); padding: 16px 20px 18px 23px; }",
  ".stall::before { content: \"\"; position: absolute; left: 0; top: 0; bottom: 0; width: 3px;",
  "  background: var(--semantic-color-status-warn); }",
  ".stall > .head { margin-bottom: 11px; }",
  ".stall-step { display: flex; align-items: center; flex-wrap: wrap; gap: 3px 9px; margin: 0;",
  "  font: 500 12.5px/1.3 var(--mono); color: var(--semantic-color-status-warn-text); }",
  ".stall-step .to { color: var(--semantic-color-fg-faint); }",
  ".stall-said { font: 17px/1.4 var(--serif); color: var(--semantic-color-fg-strong); margin: 7px 0 0; text-wrap: pretty; }",
  ".stall-why { margin: 16px 0 0; font: 600 10px/1.25 var(--sans); letter-spacing: .14em; text-transform: uppercase;",
  "  color: var(--semantic-color-fg-muted); }",
  ".numbers.stall-n { grid-template-columns: minmax(0, 1fr); margin-top: 6px; background: none; border: 0;",
  "  border-radius: 0; box-shadow: none; overflow: visible; }",
  ".numbers.stall-n .c { display: grid; grid-template-columns: 3.4ch minmax(0, 1fr); column-gap: 14px; padding: 9px 0;",
  "  box-shadow: none; border-top: 1px solid var(--semantic-color-border-default); }",
  ".numbers.stall-n .c:first-child { border-top: 0; }",
  ".numbers.stall-n b { grid-column: 1; grid-row: 1 / 3; align-self: center; text-align: right; font-size: 21px; }",
  ".numbers.stall-n b + span { grid-column: 2; grid-row: 1; margin-top: 0; }",
  ".numbers.stall-n .status { grid-column: 2; grid-row: 2; margin-top: 2px; }",
  ".stall > .go { display: inline-block; margin-top: 15px; }",
  "@media (max-width: 1100px) {",
  "  .desk-grid { grid-template-columns: minmax(0, 1fr) 300px; }",
  "}",
  "@media (max-width: 960px) {",
  "  .desk-grid { grid-template-columns: minmax(0, 1fr); }",
  "}",
  "@media (max-width: 640px) {",
  "  .fn-card { padding: 12px 16px 16px; }",
  "  .fn-step { grid-template-columns: 4.2ch minmax(0, 1fr); column-gap: 13px; }",
  "  .fn-v { font-size: 23px; }",
  "  .fn-lbl { font-size: 14.5px; }",
  "  /* the drop and the share carried are two lines on a phone, not one squeezed line */",
  "  .fn-kept { margin-left: 0; flex: 1 0 100%; }",
  "}",
  "@media print {",
  "  .desk-grid { display: block; } .desk-grid > * + * { margin-top: 20px; }",
  "  .fn-card, .stall { box-shadow: none; break-inside: avoid; }",
  "}",
].join("\n");

const PAGE_CSS = {
  "reach-out-card": [
    "/* The card is read standing up, sixty seconds before a first call, and most often on a phone. So it is one",
    "   narrow column at every width, in the order the call is made: who they are, who to ring, the way in, the",
    "   words to open with beside the words to keep off, and only then what might fit. Nothing is put in a rail,",
    "   because a rail is a thing to look across at, and there is no time to look across at anything. */",
    "/* the column is capped rather than the frame, so the card's left edge is the masthead's left edge, the way",
    "   the sheet on the other family page stands under its own banner */",
    ".wrap > * { max-width: 960px; }",
    ".wrap > .block + .block { margin-top: 26px; }",
    "/* who they are and why now, the line {{assistant}} wrote for this card, set off by a petrol rule */",
    ".who-why { margin: 16px 0 0; max-width: 80ch; padding: 1px 0 1px 16px; border-left: 2px solid var(--semantic-color-accent-default); }",
    ".who-why p { font: 16.5px/1.5 var(--serif); color: var(--semantic-color-fg-strong); margin: 0; }",
    "",
    "/* the family is one object, not a stack of them: the one who decides stands at the head of it under the",
    "   petrol rule, and everyone else the desk holds follows on a line each. A number is set in the page's own",
    "   ink wherever the desk has one, because a number read off a screen while dialling is the point of the block */",
    ".fam-card { background: var(--semantic-color-bg-paper); border: 1px solid var(--semantic-color-border-default);",
    "  border-top: 2px solid var(--semantic-color-accent-default);",
    "  border-radius: 0 0 var(--semantic-radius-card) var(--semantic-radius-card);",
    "  box-shadow: var(--semantic-shadow-card); overflow: hidden; }",
    ".dm { padding: 15px 20px 17px; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px 20px;",
    "  align-items: center; }",
    ".dm-who { min-width: 0; }",
    ".dm-who b { display: block; font: 600 22px/1.2 var(--serif); color: var(--semantic-color-fg-strong); overflow-wrap: anywhere; }",
    ".dm-who .role { display: block; font-size: 13px; line-height: 1.4; color: var(--semantic-color-fg-muted); margin-top: 3px; }",
    ".dm-who .chip { margin: 8px 0 0; }",
    ".dm-num { text-align: right; min-width: 0; }",
    ".dm-num .n { display: block; font: 500 21px/1.2 var(--mono); font-variant-numeric: tabular-nums;",
    "  color: var(--semantic-color-accent-default); overflow-wrap: anywhere; }",
    ".dm-num .n.nil { font: italic 15px/1.3 var(--serif); color: var(--semantic-color-fg-faint); }",
    ".dm-num .w { display: block; font: 600 9.5px/1 var(--sans); letter-spacing: .14em; text-transform: uppercase;",
    "  color: var(--semantic-color-fg-muted); margin-bottom: 5px; }",
    "/* everyone else in the family, one line each under the one who decides */",
    ".kin { list-style: none; margin: 0; padding: 0 20px; border-top: 1px solid var(--semantic-color-border-default); }",
    ".kin li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 16px; align-items: baseline;",
    "  padding: 11px 0; border-top: 1px solid var(--semantic-color-border-default); }",
    ".kin li:first-child { border-top: 0; }",
    ".kin b { font: 600 15.5px/1.3 var(--serif); color: var(--semantic-color-fg-strong); overflow-wrap: anywhere; }",
    ".kin .role { display: block; font-size: 12.5px; line-height: 1.4; color: var(--semantic-color-fg-muted); margin-top: 1px; }",
    ".kin .n { font: 500 14px/1.3 var(--mono); font-variant-numeric: tabular-nums;",
    "  color: var(--semantic-color-accent-default); white-space: nowrap; }",
    ".kin .n.nil { font: italic 13px/1.3 var(--serif); color: var(--semantic-color-fg-faint); }",
    ".hint { margin: 0; padding: 13px 20px 14px; border-top: 1px solid var(--semantic-color-border-default);",
    "  font: italic 13.5px/1.45 var(--serif); color: var(--semantic-color-fg-muted); }",
    "",
    "/* the routes, warmest first. A route out of our own records means somebody here already knows them, so it",
    "   is the one worth a card and the one petrol edge on the page; the rest are ways to the switchboard and are",
    "   set as a tight list under it. Every route, card or line, keeps all five of the things that make it usable:",
    "   what kind of route it is, how it runs, on what evidence, from which register, and when it was seen. */",
    ".routes { display: grid; gap: 10px; }",
    ".routes .card { padding: 13px 18px 14px 21px; }",
    ".routes .card.is-warm { --edge: var(--semantic-color-accent-default); }",
    ".kind { font: 600 13.5px/1.3 var(--sans); letter-spacing: .01em; color: var(--semantic-color-accent-default);",
    "  min-width: 0; overflow-wrap: anywhere; }",
    ".routes .how { font: 15.5px/1.45 var(--serif); color: var(--semantic-color-fg-strong); margin: 7px 0 0; text-wrap: pretty; }",
    ".routes .foot { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 14px; margin-top: 9px;",
    "  font-size: 12.5px; line-height: 1.4; color: var(--semantic-color-fg-muted); }",
    ".routes .foot .src { color: var(--semantic-color-accent-default); font-weight: 500; }",
    ".routes .card .age { font-size: 12px; }",
    ".routes .card .say { margin-top: 8px; }",
    ".ways { list-style: none; margin: 0; padding: 2px 20px; background: var(--semantic-color-bg-paper);",
    "  border: 1px solid var(--semantic-color-border-default); border-radius: var(--semantic-radius-card);",
    "  box-shadow: var(--semantic-shadow-card); }",
    ".ways.after { margin-top: 10px; }",
    ".ways li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 22px; align-items: baseline;",
    "  padding: 11px 0; border-top: 1px solid var(--semantic-color-border-default); }",
    ".ways li:first-child { border-top: 0; }",
    ".ways .how { display: block; font: 14.5px/1.45 var(--serif); color: var(--semantic-color-fg-strong);",
    "  margin-top: 2px; text-wrap: pretty; }",
    ".ways .how.nil { font-style: italic; color: var(--semantic-color-fg-muted); }",
    ".ways .src { display: flex; align-items: baseline; justify-content: flex-end; flex-wrap: wrap; gap: 4px 10px;",
    "  font-size: 12.5px; line-height: 1.5; color: var(--semantic-color-fg-muted); text-align: right; }",
    ".ways .src .d { font: 12px/1.5 var(--mono); color: var(--semantic-color-fg-muted); white-space: nowrap; }",
    "",
    "/* what to say and what not to say, read together and never one without the other */",
    ".pair.words { gap: 22px 18px; margin-top: 26px; }",
    ".pair.words > .block { margin-top: 0; }",
    ".opener { background: var(--semantic-color-bg-paper); border: 1px solid var(--semantic-color-border-default);",
    "  border-left: 3px solid var(--semantic-color-accent-default); border-radius: var(--semantic-radius-card);",
    "  box-shadow: var(--semantic-shadow-card); padding: 14px 20px 16px; }",
    ".opener p.pad { background: none; border: 0; border-radius: 0; box-shadow: none; padding: 0; margin: 0;",
    "  font: 17px/1.5 var(--serif); color: var(--semantic-color-fg-strong); text-wrap: pretty; }",
    ".opener p.pad + p.pad { margin-top: 9px; }",
    ".opener p.pad.nil { font: italic 15px/1.45 var(--serif); color: var(--semantic-color-fg-muted); }",
    ".opener .say { margin: 12px 0 0; font-size: 12px; line-height: 1.5; color: var(--semantic-color-fg-faint); }",
    "/* a crossed-out mark, drawn by the sheet and not by a glyph in the row, so each line of the list is the",
    "   sentence and nothing else; the marks carry no colour, because nothing here is waiting on the reader */",
    "ul.avoid { list-style: none; background: var(--semantic-color-bg-paper); border: 1px solid var(--semantic-color-border-default);",
    "  border-radius: var(--semantic-radius-card); box-shadow: var(--semantic-shadow-card); padding: 4px 20px; margin: 0; }",
    "ul.avoid li { position: relative; padding: 10px 0 10px 24px; border-top: 1px solid var(--semantic-color-border-default);",
    "  font-size: 14px; line-height: 1.5; color: var(--semantic-color-fg-default); }",
    "ul.avoid li:first-child { border-top: 0; }",
    "ul.avoid li::before { content: \"\\00d7\"; position: absolute; left: 2px; top: 10px; font: 15px/1.5 var(--mono);",
    "  color: var(--semantic-color-fg-faint); }",
    "",
    "/* the tail of the page, for after the call: what might fit, then the signals it was fitted to */",
    ".fits { background: var(--semantic-color-bg-paper); border: 1px solid var(--semantic-color-border-default);",
    "  border-radius: var(--semantic-radius-card); box-shadow: var(--semantic-shadow-card); padding: 11px 18px 8px; }",
    ".fits .chip { margin: 3px 6px 6px 0; }",
    "@media (max-width: 760px) {",
    "  .pair.words { grid-template-columns: minmax(0, 1fr); }",
    "}",
    "@media (max-width: 640px) {",
    "  /* on a phone the number goes under the name rather than fighting it for the line, and a route's evidence",
    "     sits under the route rather than in a column of its own that has nowhere left to stand */",
    "  .dm { grid-template-columns: minmax(0, 1fr); gap: 12px; }",
    "  .dm-num { text-align: left; }",
    "  .dm-num .n { font-size: 24px; }",
    "  .kin li { grid-template-columns: minmax(0, 1fr); gap: 4px; }",
    "  .kin .n { white-space: normal; }",
    "  .ways { padding: 2px 16px; }",
    "  .ways li { grid-template-columns: minmax(0, 1fr); gap: 6px; }",
    "  .ways .src { justify-content: flex-start; text-align: left; }",
    "}",
    "@media print {",
    "  .fam-card, .ways, .opener, ul.avoid, .fits, .routes .card { box-shadow: none; break-inside: avoid; }",
    "  .pair.words { display: grid; }",
    "}",
    "",
  ].join("\n"),
  "room-brief": [
    "/* The brief is a document, not a console: it is read through once and remembered, so it is set as one sheet",
    "   with its heads in the margin and its sentences on a reading measure. Nothing on it is scanned for a count,",
    "   and nothing on it moves; what it has instead is a claim, which the colophon states and every line keeps:",
    "   each fact says where it came from. */",
    "/* one measure for the whole document: the colophon, the contents and the sheet stand on the same two edges,",
    "   and the sheet is only as wide as its reading column and its margin need */",
    ".colophon { max-width: 880px; margin: 18px 0 0; background: var(--semantic-color-bg-paper);",
    "  border: 1px solid var(--semantic-color-border-default); border-top: 2px solid var(--semantic-color-accent-default);",
    "  border-radius: 0 0 var(--semantic-radius-card) var(--semantic-radius-card); box-shadow: var(--semantic-shadow-card);",
    "  padding: 14px 20px 15px; }",
    ".colophon .said { margin: 0; font: 15px/1.55 var(--serif); color: var(--semantic-color-fg-strong); text-wrap: pretty; }",
    ".colophon .said .tag { margin-right: 9px; vertical-align: 2px; color: var(--semantic-color-accent-default);",
    "  border-color: var(--semantic-color-accent-default); }",
    "/* the one word to settle: two pages in this kit are called a brief for a meeting, and only one of them is",
    "   this. The page says which it is in its own words, so nobody in the room has to be told */",
    ".colophon .apart { margin: 9px 0 0; padding-left: 14px; border-left: 2px solid var(--semantic-color-border-strong);",
    "  font: 14px/1.5 var(--sans); color: var(--semantic-color-fg-muted); text-wrap: pretty; }",
    ".colophon .when { display: block; margin: 11px 0 0; padding-top: 10px;",
    "  border-top: 1px solid var(--semantic-color-border-default);",
    "  font: 12.5px/1.4 var(--mono); color: var(--semantic-color-fg-muted); }",
    "",
    "/* the seven heads, as the way in and the way back: the shape of the brief before it is read */",
    ".contents { max-width: 880px; }",
    ".contents .jump { white-space: normal; text-align: left; }",
    "",
    "/* the sheet: a margin column carrying each head and a reading column carrying its sentences, with the rule",
    "   between them running the height of the section, the way a memo is set */",
    ".block.prose.sheet { max-width: 880px; padding: 4px 36px 30px; }",
    ".sh { display: grid; grid-template-columns: 204px minmax(0, 1fr); gap: 0 28px; padding: 24px 0 6px;",
    "  border-top: 1px solid var(--semantic-color-border-default); }",
    ".sh:first-child { border-top: 0; }",
    ".sh-h { position: relative; padding-right: 30px; border-right: 1px solid var(--semantic-color-border-default); }",
    ".sh-h::before { content: \"\"; position: absolute; right: -4px; top: 9px; width: 7px; height: 7px; border-radius: 50%;",
    "  background: var(--semantic-color-accent-default); }",
    ".block.prose .sh-h h2 { margin: 0; font: 600 17px/1.3 var(--serif); letter-spacing: -0.01em;",
    "  color: var(--semantic-color-fg-strong); text-wrap: balance; }",
    ".sh-b { min-width: 0; }",
    ".block.prose .sh-b > :last-child { margin-bottom: 0; }",
    ".block.prose .sh-b li { margin-bottom: 7px; }",
    ".block.prose .sh-b li::marker { color: var(--semantic-color-accent-default); }",
    "/* a section with no heading of its own keeps the measure the rest are read on */",
    ".sh.bare { grid-template-columns: minmax(0, 1fr); }",
    ".block.prose .nothing { font: italic 15px/1.5 var(--serif); color: var(--semantic-color-fg-muted); margin: 18px 0; }",
    "@media (max-width: 960px) {",
    "  /* the margin column has nowhere to stand: the head goes above its sentences, with the rule under it */",
    "  .sh { grid-template-columns: minmax(0, 1fr); gap: 10px; padding-top: 22px; }",
    "  .sh-h { padding: 0 0 9px; border-right: 0; border-bottom: 1px solid var(--semantic-color-border-default); }",
    "  .sh-h::before { right: auto; left: 0; top: auto; bottom: -4px; }",
    "  .sh-b { max-width: none; }",
    "}",
    "@media (max-width: 640px) {",
    "  .block.prose.sheet { padding: 0 20px 22px; }",
    "  .colophon { padding: 12px 16px 13px; }",
    "}",
    "@media print {",
    "  .colophon, .block.prose.sheet { box-shadow: none; }",
    "  .contents { display: none; }",
    "  .block.prose.sheet { border: 0; padding: 0; max-width: none; }",
    "  .sh { break-inside: avoid; grid-template-columns: 180px minmax(0, 1fr); }",
    "}",
    "",
  ].join("\n"),
  // row E6: the seat pages' own styles; the rep console has none of its own
  "rm-console": [
    "/* the RM's week: a column a day on the scale of hours, a meeting a card at its start with its brief's state on its edge */",
    ".wk { background: var(--semantic-color-bg-paper); border: 1px solid var(--semantic-color-border-default);",
    "  border-radius: var(--semantic-radius-card); box-shadow: var(--semantic-shadow-card); padding: 12px 16px 16px 12px; }",
    ".wk-body { display: grid; grid-template-columns: 38px repeat(var(--wk-days), minmax(0, 1fr)); }",
    ".wk-dh { display: flex; align-items: center; gap: 8px; height: 34px; margin: 0; padding: 0 10px;",
    "  font: 500 12.5px/1 var(--mono); color: var(--semantic-color-fg-strong); white-space: nowrap; }",
    ".wk-dh .tag { color: var(--semantic-color-accent-default); border-color: var(--semantic-color-accent-default); }",
    ".wk-dh .n { margin-left: auto; font: 11px/1 var(--mono); color: var(--semantic-color-fg-faint); }",
    ".wk-track { position: relative; }",
    ".wk-track .h { position: absolute; left: 0; right: 0; border-top: 1px dashed var(--semantic-color-border-default); }",
    ".wk-axis .h { border: 0; }",
    ".wk-axis .h span { position: absolute; top: -7px; right: 8px; font: 11px/1 var(--mono); color: var(--semantic-color-fg-faint); }",
    ".wk-day { min-width: 0; border-left: 1px solid var(--semantic-color-border-default); }",
    ".wk-day.is-today .wk-dh { color: var(--semantic-color-accent-default); }",
    ".wk-day.is-today .wk-track { background: var(--semantic-color-accent-soft); }",
    ".wk-open { position: absolute; top: 8px; left: 10px; right: 8px; margin: 0; font: italic 13.5px/1.3 var(--serif);",
    "  color: var(--semantic-color-fg-faint); }",
    ".mt { position: absolute; left: 6px; right: 6px; margin: 0; background: var(--semantic-color-bg-paper);",
    "  border: 1px solid var(--semantic-color-border-default); border-radius: var(--semantic-radius-control);",
    "  box-shadow: var(--semantic-shadow-card); padding: 7px 9px 9px 12px; overflow: hidden; }",
    ".mt::before { content: \"\"; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--edge); }",
    ".mt.k-ok { --edge: var(--semantic-color-accent-default); }",
    ".mt.k-due { --edge: var(--semantic-color-status-warn); }",
    ".mt-top { display: flex; align-items: baseline; justify-content: space-between; gap: 4px 8px; flex-wrap: wrap; }",
    ".mt-top .t { font: 500 14px/1.2 var(--mono); color: var(--semantic-color-fg-strong); }",
    ".mt-top .status { font-size: 11.5px; line-height: 1.2; color: var(--semantic-color-fg-muted); }",
    ".mt-fam { font: 600 15px/1.25 var(--serif); color: var(--semantic-color-fg-strong); margin: 5px 0 0; overflow-wrap: anywhere; }",
    ".mt-what { font-size: 12.5px; line-height: 1.3; color: var(--semantic-color-fg-muted); margin: 1px 0 0; overflow-wrap: anywhere; }",
    ".mt-go { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px; margin-top: 8px; }",
    ".mt-go:empty { display: none; }",
    ".mt-go .pill { font-size: 12px; padding: 5px 9px 5px 8px; white-space: normal; }",
    "/* below the week, the book on the left, and on the right what asks: the calendar, then the promises */",
    ".rm-grid { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 26px; margin-top: 28px; align-items: start; }",
    "@media (max-width: 1099px) {",
    "  /* the week as an agenda: a day a row, its meetings side by side; an open day is one quiet line */",
    "  .wk { padding: 4px 16px 6px; }",
    "  .wk-body { display: block; }",
    "  .wk-axis { display: none; }",
    "  .wk-day { display: grid; grid-template-columns: 150px minmax(0, 1fr); gap: 4px 14px; align-items: start;",
    "    border-left: 0; padding: 12px 0; }",
    "  .wk-day + .wk-day { border-top: 1px solid var(--semantic-color-border-default); }",
    "  .wk-dh { height: auto; padding: 8px 0 0; }",
    "  .wk-dh .n { display: none; }",
    "  .wk-day.is-today .wk-track { background: none; }",
    "  .wk-track { height: auto !important; display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 10px; }",
    "  .wk-track .h { display: none; }",
    "  .wk-open { position: static; padding-top: 6px; }",
    "  /* the card keeps its own positioning, or its edge bar is drawn against the day's whole track instead */",
    "  .mt { position: relative; top: auto !important; }",
    "}",
    "@media (max-width: 960px) {",
    "  .rm-grid { grid-template-columns: minmax(0, 1fr); }",
    "  .rm-grid > .col, .rm-grid > .rail { display: contents; }",
    "  .rm-grid > .col > *, .rm-grid > .rail > * { margin-top: 0; }",
    "  .rm-grid #cal { order: 1; } .rm-grid #book { order: 2; } .rm-grid #promises { order: 3; } .rm-grid .talk { order: 4; }",
    "}",
    "@media (max-width: 640px) {",
    "  /* eight counts two across is four rows before the week begins, and the jumps are a second way to reach",
    "     sections that are a thumb's scroll apart: three across, and the week starts in the first screen */",
    "  .jumps { display: none; }",
    "  .numbers { grid-template-columns: repeat(3, minmax(0, 1fr)); }",
    "  .numbers .c { padding: 11px 12px 10px; }",
    "  .numbers .c:last-child:nth-child(odd) { grid-column: auto; }",
    "  .wk-day { grid-template-columns: minmax(0, 1fr); gap: 8px; }",
    "  .wk-dh { padding-top: 0; }",
    "  .wk-track { grid-template-columns: minmax(0, 1fr); }",
    "}",
    "@media print {",
    "  .rm-grid { display: block; } .rm-grid > * > * + * { margin-top: 20px; } .rm-grid .rail { margin-top: 20px; }",
    "  .mt, .wk { box-shadow: none; break-inside: avoid; }",
    "}",
    "",
  ].join("\n"),
  "lead-gen": FUNNEL_CSS + [
    "",
    "/* the seats, in the desk's own order and never ranked: the week's four columns grouped, then what asks */",
    ".seats thead tr:first-child th { vertical-align: bottom; padding-bottom: 4px; }",
    ".seats th.grp { font-size: 9px; color: var(--semantic-color-fg-faint);",
    "  border-bottom: 1px solid var(--semantic-color-border-strong); }",
    ".seats td.seat { font: 600 14.5px/1.3 var(--serif); color: var(--semantic-color-fg-strong); white-space: nowrap; }",
    ".seats td.nil { color: var(--semantic-color-fg-faint); }",
    ".seats td.ask { color: var(--semantic-color-status-warn-text); }",
    ".seats td.doing { font-size: 13px; line-height: 1.45; color: var(--semantic-color-fg-muted); }",
    ".seats tr.team td { border-top: 1.5px solid var(--semantic-color-fg-strong); }",
    ".wrap > .pair { margin-top: 28px; }",
    "@media (max-width: 640px) {",
    "  /* the head row is folded away here, so the first seat opens the table with no rule above it */",
    "  .seats tbody tr:first-child { border-top: 0; }",
    "  /* a row is a block now, so the team's heavy rule goes over the block, not under each of its values */",
    "  .seats tr.team { border-top: 1.5px solid var(--semantic-color-fg-strong); }",
    "  .seats tr.team td { border-top: 0; }",
    "}",
    "",
  ].join("\n"),
  "snapshot": FUNNEL_CSS + [
    "",
    "/* the moment the page was taken, over the days it counts: the stamp is the page, so it is set in the",
    "   page's own ink and not left to the masthead's small line */",
    ".taken { display: flex; align-items: baseline; flex-wrap: wrap; gap: 4px 14px; margin: 14px 0 0;",
    "  font: 12.5px/1.4 var(--mono); color: var(--semantic-color-fg-muted); }",
    ".taken b { font-weight: 500; color: var(--semantic-color-fg-strong); }",
    ".taken .sep { color: var(--semantic-color-fg-faint); }",
    "/* every seat's week, in the desk's own order and never ranked: what it carries, then the four the console counts */",
    ".week-t thead tr:first-child th { vertical-align: bottom; padding-bottom: 4px; }",
    ".week-t th.grp { font-size: 9px; color: var(--semantic-color-fg-faint);",
    "  border-bottom: 1px solid var(--semantic-color-border-strong); }",
    ".week-t td.seat { font: 600 14.5px/1.3 var(--serif); color: var(--semantic-color-fg-strong); white-space: nowrap; }",
    ".week-t td.nil { color: var(--semantic-color-fg-faint); }",
    ".week-t tr.team td { border-top: 1.5px solid var(--semantic-color-fg-strong); }",
    "/* the split and the RMs are read together, so they share a line; the hand-overs are a ledger under both,",
    "   where a line long enough to name who handed what has the width to be read. The frame is the funnel's own",
    "   (`.desk-grid`, funnel.css), so the rail is the same width here as there at every size and in print */",
    ".seam-grid { grid-template-areas: \"fig rms\" \"rows rows\"; row-gap: 20px; }",
    ".rm-side { grid-area: rms; } .seam-rows { grid-area: rows; }",
    ".seam { grid-area: fig; background: var(--semantic-color-bg-paper);",
    "  border: 1px solid var(--semantic-color-border-default);",
    "  border-top: 2px solid var(--semantic-color-accent-default);",
    "  border-radius: 0 0 var(--semantic-radius-card) var(--semantic-radius-card);",
    "  box-shadow: var(--semantic-shadow-card); padding: 15px 20px 18px; }",
    ".seam-said { font: 17px/1.4 var(--serif); color: var(--semantic-color-fg-strong); margin: 0; text-wrap: pretty; }",
    ".seam-said em { font-style: normal; color: var(--semantic-color-accent-default); }",
    "/* the split as one band: the whole band is what was handed on, and each part is its own share of it */",
    ".seam-bar { display: flex; height: 13px; margin-top: 14px; border-radius: 3px; overflow: hidden;",
    "  background: var(--semantic-color-bg-sheet); box-shadow: inset 0 0 0 1px var(--semantic-color-border-default); }",
    ".seam-bar span { display: block; min-width: 0; }",
    ".p-met { background: var(--semantic-color-accent-default); }",
    ".p-on_calendar { background: var(--semantic-color-accent-default); opacity: .55; }",
    ".p-stalled { background: var(--semantic-color-status-warn); }",
    ".seam-key { list-style: none; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px;",
    "  margin: 14px 0 0; padding: 0; }",
    ".seam-key li { display: grid; grid-template-columns: 9px minmax(0, 1fr); column-gap: 10px; }",
    ".seam-key .sw { width: 9px; height: 9px; margin-top: 6px; border-radius: 2px;",
    "  box-shadow: inset 0 0 0 1px var(--semantic-color-border-strong); }",
    ".seam-key b { font: 500 21px/1.15 var(--mono); font-variant-numeric: tabular-nums; color: var(--semantic-color-fg-strong); }",
    ".seam-key .w { display: block; font: 600 10px/1.3 var(--sans); letter-spacing: .14em; text-transform: uppercase;",
    "  color: var(--semantic-color-fg-default); margin-top: 2px; }",
    ".seam-key .said { display: block; font-size: 12px; line-height: 1.4; color: var(--semantic-color-fg-muted); margin-top: 3px; }",
    "/* only a part that has something in it is coloured, as every count in the house is: nothing stalled is the",
    "   week's best news and must never be drawn as the thing that asks (macros.html.j2, the `number` macro) */",
    ".seam-key .k-stalled b { color: var(--semantic-color-status-warn-text); }",
    ".seam-rows .d { align-self: center; }",
    "/* the RMs in the rail: a row there has no room for a third column, so what came to each one sits under the",
    "   name, the way the rails on the other pages set a row (base.html.j2) */",
    ".rm-side .list li { grid-template-columns: 18px minmax(0, 1fr); }",
    ".rm-side .list b { font-size: 14px; }",
    "/* the two counts are a line each, so neither is ever broken in the middle of its own phrase */",
    ".rm-side .more > span { display: block; }",
    ".rm-side .list .d { grid-column: 2; margin-top: 3px; font-variant-numeric: tabular-nums; }",
    ".rm-note { margin: 0 0 11px; font: italic 13px/1.45 var(--serif); color: var(--semantic-color-fg-muted); }",
    "/* one week, and nothing older on this desk to set it against */",
    ".close { max-width: 80ch; margin: 24px 0 0; font: italic 15px/1.55 var(--serif); color: var(--semantic-color-fg-muted);",
    "  padding-left: 16px; border-left: 1px solid var(--semantic-color-border-strong); text-wrap: pretty; }",
    "/* the rail's widths are the frame's at every size; only the order of the three areas is this page's */",
    "@media (max-width: 960px) {",
    "  .seam-grid { grid-template-areas: \"fig\" \"rms\" \"rows\"; }",
    "}",
    "@media (max-width: 640px) {",
    "  .week-t tbody tr:first-child { border-top: 0; }",
    "  .week-t tr.team { border-top: 1.5px solid var(--semantic-color-fg-strong); }",
    "  .week-t tr.team td { border-top: 0; }",
    "  .seam-key { grid-template-columns: minmax(0, 1fr); gap: 12px; }",
    "  /* a hand-over is a block here, its state under the line that says who handed it on */",
    "  .seam-rows .list li { grid-template-columns: 18px minmax(0, 1fr); }",
    "  .seam-rows .list .d { grid-column: 2; margin-top: 4px; }",
    "}",
    "@media print {",
    "  .seam { box-shadow: none; break-inside: avoid; }",
    "}",
    "",
  ].join("\n"),
  "summary-card": [
    ".summary { max-width: 720px; margin: 18px 0 0; background: var(--semantic-color-bg-paper);",
    "  border: 1px solid var(--semantic-color-border-default); border-top: 2px solid var(--semantic-color-accent-default);",
    "  border-radius: 0 0 var(--semantic-radius-card) var(--semantic-radius-card); box-shadow: var(--semantic-shadow-card); }",
    ".summary .row { display: grid; grid-template-columns: 130px minmax(0, 1fr); gap: 4px 18px; padding: 13px 20px;",
    "  border-top: 1px solid var(--semantic-color-border-default); }",
    ".summary .row:first-child { border-top: 0; }",
    ".summary .k { font: 600 9.5px/1.9 var(--sans); letter-spacing: .12em; text-transform: uppercase; color: var(--semantic-color-fg-muted); }",
    ".summary .v { font-size: 15px; line-height: 1.5; color: var(--semantic-color-fg-strong); margin: 0; min-width: 0; }",
    ".summary .v .sub { display: block; font-size: 13px; color: var(--semantic-color-fg-muted); margin-top: 2px; }",
    ".summary .v .n { font-family: var(--mono); }",
    ".summary .nil { color: var(--semantic-color-fg-faint); }",
    ".summary-foot { max-width: 720px; font-size: 12px; line-height: 1.5; color: var(--semantic-color-fg-faint); margin: 10px 0 0; }",
    "@media (max-width: 560px) {",
    "  .summary .row { grid-template-columns: minmax(0, 1fr); padding: 11px 16px; }",
    "}",
    "@media print { .summary { box-shadow: none; break-inside: avoid; } }",
    "",
  ].join("\n"),
};

module.exports = { BASE, FOUNDATION, MARK, DRAWINGS, PAGE_CSS };
